import csv
import sys


def count_non_empty(filepath):
    counts = {}
    with open(filepath, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print("CSV 文件为空")
            return
        counts = {col: 0 for col in header}
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1

    for col, count in counts.items():
        print(f"{col}: {count}")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件路径>")
        sys.exit(1)
    count_non_empty(sys.argv[1])
